<?php
$where=['1=1'];$args=[];$search=text_input($_GET,'q',160);$status=text_input($_GET,'status',10);$gov=text_input($_GET,'governorate',120);
if($search!==''){$where[]='(a.name LIKE ? OR a.governorate LIKE ? OR a.district LIKE ? OR a.locality LIKE ? OR a.identifier LIKE ?)';$args=array_fill(0,5,'%'.$search.'%');}
if(in_array($status,['active','inactive'],true)){$where[]='a.active=?';$args[]=$status==='active'?1:0;}
if($gov!==''){$where[]='a.governorate=?';$args[]=$gov;}
$areas=rows("SELECT a.*,(SELECT COUNT(*) FROM orders o WHERE o.delivery_area_id=a.id) AS order_count,(SELECT COUNT(*) FROM orders o WHERE o.delivery_area_id=a.id AND o.status='completed') AS delivered_count FROM delivery_areas a WHERE ".implode(' AND ',$where).' ORDER BY a.governorate,a.district,a.locality,a.name',$args);
?>
<form class="panel form-grid" method="get" action="/admin/delivery"><label>Search areas<input name="q" value="<?= e($search) ?>" placeholder="Name, town, district or code"></label><label>Status<select name="status"><option value="">All statuses</option><option value="active" <?= $status==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $status==='inactive'?'selected':'' ?>>Inactive</option></select></label><label>Governorate<select name="governorate"><option value="">All governorates</option><?php foreach(rows('SELECT DISTINCT governorate FROM delivery_areas ORDER BY governorate') as $g): ?><option <?= $gov===$g['governorate']?'selected':'' ?>><?= e($g['governorate']) ?></option><?php endforeach ?></select></label><button class="button">Filter areas</button><a href="/admin/delivery">Reset</a></form>
<div class="panel table-scroll"><table><thead><tr><th>Area</th><th>Rate / minimum</th><th>Status / delivery</th><th>Orders</th><th>Actions</th></tr></thead><tbody><?php foreach($areas as $a): ?><tr><td><strong><?= e($a['name']) ?></strong><small><?= e(implode(' / ',array_filter([$a['governorate'],$a['district'],$a['locality'],$a['identifier']]))) ?></small><small><?= e($a['notes']) ?></small></td><td><?= e($a['currency']) ?> <?= number_format($a['fee']/100,2) ?><small>Minimum: <?= e($a['currency']) ?> <?= number_format($a['minimum_amount']/100,2) ?></small></td><td><?= $a['active']?'Active':'Inactive' ?><small><?= e($a['estimate']) ?></small><?php if($a['currency']!==$store['currency']): ?><small class="error-text">Currency update required</small><?php endif ?></td><td><?= (int)$a['order_count'] ?> placed<small><?= (int)$a['delivered_count'] ?> completed</small></td><td><div class="table-actions"><a class="text-link" href="/admin/delivery?edit=<?= e($a['id']) ?>">Edit</a><?php foreach([($a['active']?'deactivate':'activate')=>($a['active']?'Deactivate':'Activate'),'delete'=>'Delete'] as $action=>$label): ?><form method="post" action="/admin/delivery" <?= $action==='delete'?'data-confirm="Delete this unused delivery area? Areas used by orders must be deactivated instead."':'' ?>><?= csrf_field() ?><input type="hidden" name="section" value="delivery"><input type="hidden" name="action" value="<?= $action ?>"><input type="hidden" name="id" value="<?= e($a['id']) ?>"><button class="text-button <?= $action==='delete'?'danger':'' ?>"><?= $label ?></button></form><?php endforeach ?></div></td></tr><?php endforeach ?></tbody></table><?php if(!$areas): ?><p>No delivery areas match. Add the places you deliver to and enter your actual rates.</p><?php endif ?></div>
<section class="panel"><h2>Preview a delivery fee</h2><p>This uses the same server calculation as checkout without changing your bag or customer selections. Area preview works before enabling location-based delivery.</p><form class="form-grid" method="get" action="/admin/delivery"><label>Area<select name="preview_area" required><option value="">Select an area</option><?php foreach(delivery_areas() as $a): ?><option value="<?= e($a['id']) ?>" <?= ($_GET['preview_area']??'')===$a['id']?'selected':'' ?>><?= e(delivery_label($a)) ?></option><?php endforeach ?><?php if($shipping['unsupported']==='fallback'): ?><option value="other" <?= ($_GET['preview_area']??'')==='other'?'selected':'' ?>>Other area — fallback rate</option><?php endif ?></select></label><label>Merchandise subtotal before discounts (<?= e($store['currency']) ?>)<input type="number" name="preview_subtotal" min="0" step="0.01" required value="<?= e(text_input($_GET,'preview_subtotal',20)?:'50.00') ?>"></label><button class="button">Preview delivery fee</button></form>
<?php if(!empty($_GET['preview_area'])):$preview=delivery_price(cents(text_input($_GET,'preview_subtotal',20,true)),false,text_input($_GET,'preview_area',32,true),true); ?><p role="status"><?php if($preview['status']==='ready'): ?><?= e($preview['name']) ?>: <strong><?= $preview['fee']?money($preview['fee']):'Free Delivery' ?></strong>. <?= e($preview['message']) ?><?php else: ?><?= e($preview['message']) ?><?php endif ?></p><?php endif ?></section>
